viz.option:
option = {
  title: {
    text: 'Random Scatter — x vs y',
    left: 'center'
  },
  tooltip: {
    trigger: 'item',
    formatter: '({c})'
  },
  xAxis: {
    type: 'value',
    name: 'x',
    nameLocation: 'end',
    scale: true
  },
  yAxis: {
    type: 'value',
    name: 'y',
    nameLocation: 'end',
    scale: true
  },
  series: [
    {
      name: 'Points',
      type: 'scatter',
      symbolSize: 8
    }
  ]
};

option = {
  title: {
    text: 'Bubble Chart — x, y and size',
    left: 'center'
  },
  tooltip: {
    trigger: 'item',
    formatter: 'x={c[0]}  y={c[1]}  size={c[2]}'
  },
  xAxis: {
    type: 'value',
    name: 'x',
    scale: true
  },
  yAxis: {
    type: 'value',
    name: 'y',
    scale: true
  },
  series: [
    {
      name: 'Requests',
      type: 'scatter',
      symbolSize: function (val) {
        return val[2] / 4;
      },
      itemStyle: {
        opacity: 0.7
      }
    }
  ]
};

pre.code:
xAxis: { type: 'category', data: ['00:00', '04:00', '08:00', '12:00', '16:00', '20:00'] },
yAxis: { type: 'category', data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'] },
visualMap: {
  min: 0, max: 500,
  calculable: true,
  orient: 'horizontal',
  left: 'center',
  bottom: '5%'
},
series: [{
  type: 'heatmap',
  data: [[0, 0, 5], [1, 0, 8], ...],
  label: { show: true }
}]
